// TH14 synthetic bullet aliases used by this card only.
// Native type6 (ring ball) and type8 (rice); native 0..23 keep the same slot.
// Source is a synthetic mapping approved in transcribe/th14/bullet-types.md.
const TH14_RING_BALL: int = 448;
const TH14_RICE: int = 480;

// TH14 v1.00b Extra BossCard2 / spellEx111  二鼓「怨霊アヤノツヅミ」
// Source: st07bs.ecl.txt BossCard2 1344-1387 and its closure
//   BossCard2_at 1461-1507, BossCard2_Phantom00 1389-1427,
//   BossCard2_Phantom00_at 1429-1459.
// Entry is the whole BossCard2 sub; its own timerReset starts the native 3000 frame clock.
// Independent shell: control owns the phase, the real boss runs at the source entry.

const TIME_LIMIT: int = 3424;      // 120 opening buffer + 3300 window + 4 start margin
const OPENING_BUFFER: int = 120;
const SOURCE_LIMIT: int = 3000;    // source spellEx(111, 50*60, ...) timer from entry
const SRC_ABORT_SLOT: int = 16;    // free globals slot: 1 = source timeout reached

// Source etEx 0x200000 VELTIME: a=120, r=target scalar speed, s preserves the angle.
// Direction is unchanged, so the scalar ramp equals a linear speed STEP.
xformdef SPEED_TO(target: fx) {
    step_speed(target, 120);
}

// ---------- source BossCard2_at (1461-1507) helpers ----------

// Source wait(n) inside the attack; abort at the native timeout like killAllAsync/enmKillAll.
sub atk_wait(n: int) {
    var i: int = 0;
    while i < n {
        wait(1);
        i = i + 1;
        if self_int(0) >= SOURCE_LIMIT { return; }
    }
}

// Source BossCard2_Phantom00_at 1429-1459, called at the field edge.
// Wave 1: etAim mode10, etSprite type8 color2, count 1x5, angle A +-1deg,
//         etSpeed 1.0 -> 0.7, five etOn salvos with VELTIME r=1,3,5,7,9 (same frame).
// Wave 2: etAim mode1, etSprite type6 color2, count 2x1, angle A +-90/2, speed 1.0.
// Both waves carry EX ANIM a=1: spawn position -= 4*velocity, kept per approved policy.
sub phantom_at(a: angle) {
    var ab: int = a as int;
    for s in 0..5 {
        var target: fx = (1 + 2 * s) as fx;
        for q in 0..5 {
            // mode10 (fixed alternating ring), N=1, M=5:
            // H=floor((q+1)/2)*delta, angle=A+(-1)^q*H; 1deg = 182 BAM.
            var hb: int = ((q + 1) / 2) * 182;
            var angb: int = ab + hb;
            if q % 2 != 0 { angb = ab - hb; }
            var speed: fx = 1fx;
            if q == 1 || q == 2 { speed = 0.85fx; } else if q == 3 || q == 4 { speed = 0.7fx; }
            var ang: angle = angb as angle;
            var ox: fx = 4fx * speed * cos(ang);
            var oy: fx = 4fx * speed * sin(ang);
            _ = fire(TH14_RICE, 2, $self_x - ox, $self_y - oy, speed, ang, SPEED_TO(target), none);
        }
    }
    var a1: angle = (ab + 8192) as angle;   // +45deg
    var a2: angle = (ab - 8192) as angle;   // -45deg
    _ = fire(TH14_RING_BALL, 2, $self_x - 4fx * cos(a1), $self_y - 4fx * sin(a1), 1fx, a1, none, none);
    _ = fire(TH14_RING_BALL, 2, $self_x - 4fx * cos(a2), $self_y - 4fx * sin(a2), 1fx, a2, none, none);
}

// Source BossCard2_Phantom00 1389-1427. Spawned by enmCreate relative to the boss,
// inherits F0 as its fixed direction, initial speed 1 ramping linearly to 5 over 120
// frames. On leaving the field it calls Phantom00_at with the inward angle, then deletes.
async sub phantom(dir: angle) {
    set_invuln(65535);          // no-DPS shell; source hit/flags have no target write path
    set_hurtbox(14fx);          // setHurtbox(28,28): circular branch 28*0.5
    set_hitbox(8fx);            // setHitbox(16,16): circular branch 16*0.5
    var k: int = 0;
    loop {
        if global(SRC_ABORT_SLOT) != 0 { return; }
        var speed: fx = 5fx;
        if k < 120 { speed = 1fx + 4fx * (k as fx) / 120fx; }
        move_vel_xy(0, speed * cos(dir), speed * sin(dir), EASE_LINEAR);
        wait(1);
        k = k + 1;
        // Source checks FINAL_X< -192, FINAL_X>192, FINAL_Y>448, FINAL_Y<0 in order.
        if $self_x < -192fx { phantom_at(0deg); return; }
        if $self_x > 192fx { phantom_at(180deg); return; }
        if $self_y > 448fx { phantom_at(270deg); return; }
        if $self_y < 0fx { phantom_at(90deg); return; }
    }
}

// ---------- boss movement: source moveRand(60,0,0.6) + moveLimit(0,128,280,64) ----------
// Reuses the verified shared moveRand recipe (linear speed s0*(1-k/60), per-frame clamp,
// direction zone width/4). This card: limit x[-140,140] y[96,160], inner x+-70 y112..144.

sub boss_arm_next_step() {
    var k: int = self_int(1) + 1;
    set_self_int(1, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 0.6fx * ((60 - k) as fx) / 60fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub boss_begin_dir(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(1, 0);
    boss_arm_next_step();
}

sub boss_move_rand() {
    // signed unit random * pi as unwrapped BAM int; x branches use the limit width/4.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon 0.05rad -> 522 BAM around 16384.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    boss_begin_dir(a as angle);
}

// Owns the source frame counter in self_int(0) (entry = 0) and stops at SOURCE_LIMIT.
sub boss_wait(n: int) {
    var i: int = 0;
    while i < n {
        wait(1);
        set_self_int(0, self_int(0) + 1);
        i = i + 1;
        if self_int(0) >= SOURCE_LIMIT { return; }
    }
}

sub boss_move_wait(n: int) {
    var i: int = 0;
    while i < n {
        wait(1);
        set_self_int(0, self_int(0) + 1);
        i = i + 1;
        if self_int(0) >= SOURCE_LIMIT { return; }
        boss_arm_next_step();
    }
}

// ---------- source BossCard2_at (1461-1507): phantom waves ----------

async sub boss_attack() {
    loop {
        if self_int(0) >= SOURCE_LIMIT { return; }
        // F0=-45deg; 4 creates, F0 -= 30deg, wait(10) each.
        var f: int = -8192;
        var b: int = 0;
        while b < 4 {
            _ = spawn_enemy($self_x, $self_y, 100, 0, 10, 0, phantom(f as angle));
            f = f - 5461;
            atk_wait(10);
            if self_int(0) >= SOURCE_LIMIT { return; }
            b = b + 1;
        }
        atk_wait(100);
        if self_int(0) >= SOURCE_LIMIT { return; }
        // F0=-135deg; 4 creates, F0 += 30deg, wait(10) each.
        f = -24576;
        var c: int = 0;
        while c < 4 {
            _ = spawn_enemy($self_x, $self_y, 100, 0, 10, 0, phantom(f as angle));
            f = f + 5461;
            atk_wait(10);
            if self_int(0) >= SOURCE_LIMIT { return; }
            c = c + 1;
        }
        atk_wait(140);
        if self_int(0) >= SOURCE_LIMIT { return; }
        atk_wait(60);
        if self_int(0) >= SOURCE_LIMIT { return; }
        // F0 = -45deg + RANDF2*10deg; 24 creates, F0 += 11.25deg, wait(10) each.
        var rr: int = rand(65536) - 32768;
        f = -8192 + rr * 1820 / 32768;
        var d: int = 0;
        while d < 24 {
            _ = spawn_enemy($self_x, $self_y, 100, 0, 10, 0, phantom(f as angle));
            f = f + 2048;
            atk_wait(10);
            if self_int(0) >= SOURCE_LIMIT { return; }
            d = d + 1;
        }
        atk_wait(60);
        if self_int(0) >= SOURCE_LIMIT { return; }
    }
}

// ---------- source BossCard2 entry (1344-1387) ----------

async sub source_enemy() {
    set_invuln(65535);
    set_hurtbox(24fx);          // Boss context 48x48, circular branch *0.5
    set_hitbox(24fx);
    set_self_int(0, 0);         // source frame counter, 0 = entry / timerReset
    set_self_int(1, 0);
    set_self_fx(0, 0fx);
    set_self_fx(1, 0fx);
    // Source: movePosTime(60,4,0,144); moveLimit(0,128,280,64) is applied per frame below.
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);
    boss_wait(60);              // source +60: charge ANM/sound (presentation omitted)
    boss_wait(90);              // source +150: anmSelectedPlay omitted
    spawn boss_attack();        // source @BossCard2_at() async
    // Source loop: moveRand(60,0,0.6); wait(180); repeat.
    loop {
        if self_int(0) >= SOURCE_LIMIT { break; }
        boss_move_rand();
        boss_move_wait(180);
    }
    set_global(SRC_ABORT_SLOT, 1);        // native timeout: stop this attack's emissions
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 3000, 0, 0, 0, source_enemy);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_global(SRC_ABORT_SLOT, 0);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
